styles:
.custom-widget-container {
    position: fixed;
    bottom: 20px;
    right: 20px;
    display: flex;
    flex-direction: column;
    align-items: flex-end;
    gap: 10px;
    padding: 10px;
    z-index: 9999;
}

button, #messengerButton, #shopBackWeb {
    width: 45px;
    height: 45px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: transform 0.2s, background 0.2s;
    border: none;
}

#messengerButton {
    background: #0084FF;
}

#messengerButton:hover {
    transform: scale(1.1);
    background: #0073E6;
}

#shopBackWeb {
    background: #FF4500; /* Màu đỏ cam */
}

#shopBackWeb:hover {
    transform: scale(1.1);
    background: #E03E00;
}

#messengerButton img, #shopBackWeb img {
    width: 70%;
    height: 70%;
    object-fit: contain;
}
